tool_input.command:
cd "D:\repository\苏住房防汛C端"
$cs = Get-ChildItem dist/assets -Filter *.css
Write-Host "== floating-rescue / rescue-fab in dist =="
foreach ($f in $cs) {
  $m = Select-String -Path $f.FullName -Pattern "floating-rescue|rescue-fab" -SimpleMatch
  if ($m) { Write-Host ">> $($f.Name)"; $m | ForEach-Object { Write-Host $_.Line.Substring(0,[Math]::Min(260,$_.Line.Length)) } }
}
Write-Host "== bottom:100px match count =="
($cs | Select-String -Pattern "bottom:100px" -SimpleMatch).Count

$base="http://localhost:8095"
try {
  $r = Invoke-WebRequest -Uri "$base/" -UseBasicParsing -TimeoutSec 10
  Write-Host "index.html status: $($r.StatusCode)"
  $css = [regex]::Match($r.Content, '/assets/index-[^"]+\.css').Value
  Write-Host "referenced css: $css"
  if ($css) {
    $rc = Invoke-WebRequest -Uri "$base$css" -UseBasicParsing -TimeoutSec 10
    Write-Host "css status: $($rc.StatusCode), bytes: $($rc.Content.Length)"
    Write-Host "has bottom:100px: $(($rc.Content -match 'bottom:100px'))"
  }
} catch { Write-Host "ERR: $_" }
